import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
const project = new URL('../', import.meta.url).pathname;
async function withRepo(source, fn) {
 const dir=mkdtempSync(join(tmpdir(),'cp-ci-'));
 try {
  // Same layout as the kit generated by the Team & CI view.
  await fs.mkdir(join(dir,'.codeproof','engine'),{recursive:true}); await fs.mkdir(join(dir,'src'));
  await fs.copyFile(join(project,'docs','integrations','cli.mjs'),join(dir,'.codeproof','cli.mjs'));
  await fs.copyFile(join(project,'docs','assets','acorn.mjs'),join(dir,'.codeproof','acorn.mjs'));
  await fs.copyFile(join(project,'docs','vendor','typescript.js'),join(dir,'.codeproof','typescript.cjs'));
  for(const name of await fs.readdir(join(project,'docs','assets','engine'))) await fs.copyFile(join(project,'docs','assets','engine',name),join(dir,'.codeproof','engine',name));
  await fs.cp(join(project,'docs','vendor','typescript-lib'),join(dir,'.codeproof','typescript-lib'),{recursive:true});
  await fs.writeFile(join(dir,'src','test.js'),source);
  await fs.writeFile(join(dir,'.codeproof-policy.json'),JSON.stringify({version:1,maxFiles:100,maxFileBytes:250000,failOnSeverity:'critical',failOnParseError:true,ignorePaths:['.codeproof','.git','node_modules']}));
  return await fn(dir);
 } finally { await fs.rm(dir,{recursive:true,force:true}); }
}
test('portable CI integration detects risky code and blocks at critical threshold',async()=>withRepo('function unsafe(input){return eval(input)}',async root=>{
 const x=spawnSync(process.execPath,['.codeproof/cli.mjs'],{cwd:root,encoding:'utf8'});
 assert.equal(x.status,1,x.stderr); assert.match(x.stdout,/JS_DYNAMIC_EXEC/);
 const json=JSON.parse(await fs.readFile(join(root,'codeproof-report.json'),'utf8'));
 assert.ok(json.summary.blocking>=1); assert.equal(json.execution.includes('not performed'),true);
}));
test('portable CI integration passes plain code without executing it',async()=>withRepo('export function add(a,b){return a+b;}',async root=>{
 const x=spawnSync(process.execPath,['.codeproof/cli.mjs'],{cwd:root,encoding:'utf8'});
 assert.equal(x.status,0,x.stderr); assert.match(x.stdout,/0 policy-blocking/);
}));
test('portable CI integration reports cross-file contract failures with compiler evidence',async()=>withRepo('import { missing } from "./lib.js";\nexport const run = () => missing();\n',async root=>{
 await fs.writeFile(join(root,'src','lib.js'),'export const present = 1;\n');
 const x=spawnSync(process.execPath,['.codeproof/cli.mjs'],{cwd:root,encoding:'utf8'});
 assert.ok(x.status===0||x.status===1,x.stderr);
 const json=JSON.parse(await fs.readFile(join(root,'codeproof-report.json'),'utf8'));
 const f=json.findings.find(f=>f.rule==='IMPORT_MISSING_EXPORT');
 assert.ok(f,'missing export detected');assert.equal(f.file,'src/test.js');
 assert.ok(f.analyzers.includes('typescript-compiler')&&f.analyzers.includes('integration-graph'),'deduplicated with provenance from both analyzers');
 assert.ok(json.coverage.some(r=>r.id==='typecheck'&&r.numerator===2));
 assert.match(json.execution,/not performed/);
}));
